// packages/database/src/db/relations/commerce.ts
// Grouped relations for commerce domain (generated by scripts/split-relations.ts)

import { relations } from 'drizzle-orm/relations'
import {
  EntityInstance,
  Invoice,
  Message,
  MessageParticipant,
  Organization,
  Participant,
  Plan,
  PlanSubscription,
  PlanSubscriptionHistory,
  User,
} from '../schema'

export const participantRelations = relations(Participant, ({ one, many }) => ({
  entityInstance: one(EntityInstance, {
    fields: [Participant.entityInstanceId],
    references: [EntityInstance.id],
  }),
  organization: one(Organization, {
    fields: [Participant.organizationId],
    references: [Organization.id],
  }),
  sentMessages: many(Message, {
    relationName: 'message_fromId_participant_id',
  }),
  replyToMessages: many(Message, {
    relationName: 'message_replyToId_participant_id',
  }),
  messageRoles: many(MessageParticipant),
}))

export const planSubscriptionRelations = relations(PlanSubscription, ({ one, many }) => ({
  organization: one(Organization, {
    fields: [PlanSubscription.organizationId],
    references: [Organization.id],
  }),
  plan: one(Plan, {
    fields: [PlanSubscription.planId],
    references: [Plan.id],
  }),
  scheduledPlan: one(Plan, {
    fields: [PlanSubscription.scheduledPlanId],
    references: [Plan.id],
  }),
  invoices: many(Invoice),
  history: many(PlanSubscriptionHistory),
}))

export const planRelations = relations(Plan, ({ many }) => ({
  subscriptions: many(PlanSubscription),
}))

export const planSubscriptionHistoryRelations = relations(PlanSubscriptionHistory, ({ one }) => ({
  organization: one(Organization, {
    fields: [PlanSubscriptionHistory.organizationId],
    references: [Organization.id],
  }),
  subscription: one(PlanSubscription, {
    fields: [PlanSubscriptionHistory.subscriptionId],
    references: [PlanSubscription.id],
  }),
  user: one(User, {
    fields: [PlanSubscriptionHistory.userId],
    references: [User.id],
  }),
}))

export const invoiceRelations = relations(Invoice, ({ one }) => ({
  organization: one(Organization, {
    fields: [Invoice.organizationId],
    references: [Organization.id],
  }),
  subscription: one(PlanSubscription, {
    fields: [Invoice.subscriptionId],
    references: [PlanSubscription.id],
  }),
}))
